        sink.italic_();
        sink.text(".");
        sink.paragraph_();
    } finally {
        if (sink != null) {
            sink.close();
        }
    }
    String actual = writer.toString();
    String expected = "<p>There should be no space before the <i>period</i>.</p>";
    assertEquals(expected, actual);
}

