        sink.tableCell_();
        sink.tableCell();
        sink.text("cell12");
        sink.tableCell_();
        sink.tableRow_();
        sink.tableRow();
        sink.tableCell();
        sink.table(SinkEventAttributeSet.LEFT);
        sink.tableRows(new int[] { Sink.JUSTIFY_LEFT }, false);
        sink.tableRow();
        sink.tableCell();
        sink.text("nestedTable1Cell11");
        sink.tableCell_();
        sink.tableCell();
        sink.text("nestedTable1Cell12");
        sink.tableCell_();
        sink.tableRow_();
        sink.tableRow();
        sink.tableCell();
        sink.table(SinkEventAttributeSet.RIGHT);
        sink.tableRows(new int[] { Sink.JUSTIFY_RIGHT }, false);
        sink.tableRow();
        sink.tableCell();
        sink.text("nestedTable2Cell11");
        sink.tableCell_();
        sink.tableCell();
        sink.text("nestedTable2Cell12");
        sink.tableCell_();
        sink.tableRow_();
        sink.tableRow();
        sink.tableCell();
        sink.text("nestedTable2Cell21");
        sink.tableCell_();
        sink.tableCell();
        sink.text("nestedTable2Cell22");
        sink.tableCell_();
        sink.tableRow_();
        sink.tableRows_();
        sink.tableCaption();
        sink.text("caption3");
        sink.tableCaption_();
        sink.table_();
        sink.tableCell_();
        sink.tableCell();
        sink.text("nestedTable1Cell22");
        sink.tableCell_();
        sink.tableRow_();
        sink.tableRows_();
        sink.tableCaption();
        sink.text("caption2");
        sink.tableCaption_();
        sink.table_();
        sink.tableCell_();
        sink.tableCell();
        sink.text("cell22");
        sink.tableCell_();
        sink.tableRow_();
        sink.tableRows_();
        sink.tableCaption();
        sink.text("caption&1");
        sink.tableCaption_();
        sink.table_();
    } finally {
        sink.close();
    }
    String actual = writer.toString();
    assertTrue(actual.contains("<table border=\"0\" class=\"bodyTable\">" + "<caption>caption&amp;1</caption>"));
    assertTrue(actual.contains("<table border=\"0\" class=\"bodyTable\" align=\"left\">" + "<caption>caption2</caption>"));
    assertTrue(actual.contains("<table border=\"0\" class=\"bodyTable\" align=\"right\">" + "<caption>caption3</caption>"));
    assertTrue(actual.contains("<td>cell11</td>"));
    assertTrue(actual.contains("<td>nestedTable1Cell11</td>"));
    assertTrue(actual.contains("<td>nestedTable2Cell11</td>"));
    assertTrue(actual.contains("<td>nestedTable1Cell22</td>"));
    assertTrue(actual.contains("<td>cell22</td>"));
}

