    final String text = "" + "      * item1.1 \n" + "   * item2\n" + "      * item2.1\n" + "   * item3\n" + "      * item3.1\n" + "      * item3.2\n" + "         * item3.2.1\n" + "         * item3.2.2\n" + "         * item3.2.3\n" + "      * item3.3\n" + "         * item3.3.1\n" + "   * item4";
