@Test
public final void testSectionParser() throws Exception {
    final SectionBlockParser parser = sectionParser;
    assertTrue(parser.accept("---+ Title1"));
    assertTrue(parser.accept("---++ Title2"));
    assertFalse(parser.accept(" ---++ Title3"));
    assertTrue(parser.accept("---+++ Title4"));
    assertTrue(parser.accept("---++++ Title5"));
    assertTrue(parser.accept("---+++++ Title6"));
    SectionBlock block;
    block = (SectionBlock) parser.visit("---++++ Title4", new ByLineReaderSource(new StringReader("")));
    final int level = 4;
    assertEquals("Title4", block.getTitle());
    assertEquals(level, block.getLevel());
    assertEquals(0, block.getBlocks().length);
    // ejemplo un poco m�s complejo
    block = (SectionBlock) parser.visit("---+++ Title3", new ByLineReaderSource(new StringReader("This is *a* parragraph of a section.\n" + "Some text.\n" + "---+++ Another Title" + "... and more text")));
    final SectionBlock expected = new SectionBlock("Title3", 3, new Block[] { new ParagraphBlock(new Block[] { new TextBlock("This is "), new BoldBlock(new Block[] { new TextBlock("a") }), new TextBlock(" parragraph of a section. Some text.") }) });
    assertEquals(expected, block);
}

/**
