/**
 * test Specific Links
 */
@Test
public final void testURLSpecificLinks() {
    Block[] blocks, expected;
    expected = new Block[] { new LinkBlock("http://reference.com", new TextBlock("text")) };
    blocks = textParser.parse("[[http://reference.com][text]]").toArray(TOARRAY);
    assertArrayEquals(expected, blocks);
    expected = new Block[] { new TextBlock("foo"), new LinkBlock("http://reference.com", new TextBlock("text")), new TextBlock("bar") };
    blocks = textParser.parse("foo[[http://reference.com][text]]bar").toArray(TOARRAY);
    assertArrayEquals(expected, blocks);
    expected = new Block[] { new TextBlock(" foo "), new LinkBlock("http://reference.com", new TextBlock("text")), new TextBlock(" bar ") };
    blocks = textParser.parse(" foo [[http://reference.com][text]] bar ").toArray(TOARRAY);
    assertArrayEquals(expected, blocks);
    expected = new Block[] { new LinkBlock("http://www.apache.org/licenses/LICENSE-2.0", new TextBlock("Apache License, version 2.0")), new TextBlock(". You can download it "), new WikiWordBlock("DoxiaDownload", new TextBlock("here"), resolver) };
    blocks = textParser.parse("[[http://www.apache.org/licenses/LICENSE-2.0]" + "[Apache License, version 2.0]]. You can download it " + "[[DoxiaDownload][here]]").toArray(TOARRAY);
    assertArrayEquals(expected, blocks);
}

